#!/usr/bin/env python
# KILO DEMO KERNEL - self-guided buyer demo hosted on Kaggle (Baba 2026-09-29:
# "we use the kaggle route, we tell them the steps for walking through themselves"
# + "kaggle pulls from git for the demo").
# Source of truth = GitHub (repo-catalog, synced from D drive). Embedded bytes are
# a FALLBACK only. Writes go to /kaggle/working - /kaggle/src is read-only
# (first run died there: OSError Errno 30, logged 2026-09-29).
import base64, os, re, shutil, subprocess, sys, time, urllib.request, json as _json

SRC = os.path.dirname(os.path.abspath(__file__))
WORK = "/kaggle/working" if os.path.isdir("/kaggle/working") else SRC
os.chdir(WORK)
print("[demo] python", sys.version.split()[0], "work=%s" % WORK, flush=True)
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "flask"],
               check=False)

# ---- sources: GIT FIRST (D drive -> git -> kaggle), embedded as fallback ----
GIT = "https://github.com/isearchxsolve/repo-catalog.git"
got = ""
try:
    clone = os.path.join(WORK, "repo-catalog")
    subprocess.run(["git", "clone", "--depth", "1", GIT, clone], check=True,
                   timeout=90)
    app_p = os.path.join(clone, "showcase", "app.py")
    cat_p = os.path.join(clone, "showcase", "REPO-CATALOG-V2.md")
    if not os.path.exists(cat_p):
        cat_p = os.path.join(clone, "REPO-CATALOG-V2.md")
    shutil.copy(app_p, os.path.join(WORK, "app.py"))
    shutil.copy(cat_p, os.path.join(WORK, "REPO-CATALOG-V2.md"))
    got = "git"
except Exception as e:
    print("[demo] git pull failed (%s) -> embedded fallback" % e, flush=True)
    APP_SRC = base64.b64decode('').decode("utf-8")
    CAT_SRC = base64.b64decode('').decode("utf-8")
    open(os.path.join(WORK, "app.py"), "w", encoding="utf-8").write(APP_SRC)
    open(os.path.join(WORK, "REPO-CATALOG-V2.md"), "w",
         encoding="utf-8").write(CAT_SRC)
    got = "embedded"
print("[demo] sources via %s" % got, flush=True)

env = dict(os.environ, DEMO_PORT="8899",
           DEMO_PROVISION_TOKEN="1631d62f90f53549cb97e735f6789e26901ef2623d85ce610872d2b77b624f88",
           DEMO_DB=os.path.join(WORK, "showcase.db"))
app_proc = subprocess.Popen([sys.executable, os.path.join(WORK, "app.py")],
                            env=env, cwd=WORK,
                            stdout=open(os.path.join(WORK, "app.log"), "wb"),
                            stderr=subprocess.STDOUT)
for _ in range(45):
    try:
        urllib.request.urlopen("http://127.0.0.1:8899/login", timeout=3).read()
        print("[demo] app up on 8899", flush=True); break
    except Exception:
        time.sleep(1)
else:
    print("[demo] APP FAILED", flush=True); sys.exit(3)

# ---- cloudflared quick tunnel ---------------------------------------------
cf = os.path.join(WORK, "cloudflared")
urllib.request.urlretrieve(
    "https://github.com/cloudflare/cloudflared/releases/latest/download/"
    "cloudflared-linux-amd64", cf)
os.chmod(cf, 0o755)
tf = open(os.path.join(WORK, "tunnel.log"), "wb")
tun_proc = subprocess.Popen([cf, "tunnel", "--url", "http://127.0.0.1:8899"],
                            stdout=tf, stderr=subprocess.STDOUT)
url = None
for _ in range(75):
    try:
        m = re.search(r"https://[a-z0-9-]+\.trycloudflare\.com",
                      open(os.path.join(WORK, "tunnel.log"), "rb")
                      .read().decode("utf-8", "replace"))
        if m:
            url = m.group(0); break
    except OSError:
        pass
    time.sleep(1)
if not url:
    print("[demo] NO TUNNEL URL", flush=True); sys.exit(4)

# ---- smoke credential + wire announcement ---------------------------------
sys.path.insert(0, WORK)
import app as showcase
u, p = showcase.create_user("demo-smoke", who="kaggle-smoke")
text = ("DEMO-KAGGLE UP url=%s user=%s pw=%s host=kaggle (12h session - "
        "disclose window in every mail)" % (url, u, p))
try:
    req = urllib.request.Request(
        "https://fathers-crowd-fraction-vatican.trycloudflare.com/say?token=GOLD24",
        data=_json.dumps({"body": "KILO", "text": text}).encode(),
        headers={"Content-Type": "application/json"}, method="POST")
    urllib.request.urlopen(req, timeout=20).read()
    print("[demo] announced on the wire", flush=True)
except Exception as e:
    print("[demo] wire say failed: %s" % e, flush=True)
print("PUBLIC-URL %s" % url, flush=True)
print("SMOKE-PAIR user=%s pw=%s" % (u, p), flush=True)

# ---- stay alive, health-print, exit before the session cap ----------------
for i in range(120):                       # 10h at 5 min cadence
    time.sleep(300)
    try:
        urllib.request.urlopen("http://127.0.0.1:8899/health", timeout=5).read()
        print("[demo] healthy t=%dmin" % ((i + 1) * 5), flush=True)
    except Exception as e:
        print("[demo] health FAIL %s" % e, flush=True)
print("[demo] window over - shutting down cleanly", flush=True)
for pr in (tun_proc, app_proc):
    try: pr.terminate()
    except Exception: pass
